CREATE DATABASE IF NOT EXISTS tpk_attendance_system CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE tpk_attendance_system;

CREATE TABLE campuses (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, code VARCHAR(50) NOT NULL UNIQUE, timezone VARCHAR(64) NOT NULL DEFAULT 'Africa/Lagos', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE classes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, campus_id INT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, age_label VARCHAR(80) NOT NULL, color VARCHAR(12) NOT NULL DEFAULT '#F4A340', is_active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE KEY campus_class (campus_id,name), FOREIGN KEY (campus_id) REFERENCES campuses(id) ON DELETE CASCADE);
CREATE TABLE families (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, campus_id INT UNSIGNED NOT NULL, family_code VARCHAR(80) NOT NULL UNIQUE, surname VARCHAR(120) NOT NULL, phone VARCHAR(40), email VARCHAR(150), notes TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX campus_surname(campus_id,surname), INDEX campus_phone(campus_id,phone), FOREIGN KEY(campus_id) REFERENCES campuses(id) ON DELETE CASCADE);
CREATE TABLE guardians (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, family_id INT UNSIGNED NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, phone VARCHAR(40) NOT NULL, email VARCHAR(150), relationship VARCHAR(80) NOT NULL, is_primary BOOLEAN NOT NULL DEFAULT FALSE, is_authorized BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(family_id) REFERENCES families(id) ON DELETE CASCADE);
CREATE TABLE authorized_pickups (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, family_id INT UNSIGNED NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, phone VARCHAR(40), relationship VARCHAR(80) NOT NULL, photo_note VARCHAR(255), is_active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(family_id) REFERENCES families(id) ON DELETE CASCADE);
CREATE TABLE children (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, family_id INT UNSIGNED NOT NULL, class_id INT UNSIGNED NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, date_of_birth DATE NULL, medical_notes TEXT, safeguarding_notes TEXT, is_active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(family_id) REFERENCES families(id) ON DELETE CASCADE, FOREIGN KEY(class_id) REFERENCES classes(id));
CREATE TABLE family_passes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, family_id INT UNSIGNED NOT NULL, type ENUM('PHYSICAL_QR','DIGITAL_QR','BARCODE') NOT NULL, opaque_token VARCHAR(120) NOT NULL UNIQUE, label VARCHAR(100), is_active BOOLEAN NOT NULL DEFAULT TRUE, issued_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, expires_at DATETIME NULL, FOREIGN KEY(family_id) REFERENCES families(id) ON DELETE CASCADE);
CREATE TABLE staff_users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, campus_id INT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, role ENUM('ADMIN','CHECK_IN','CLASS_LEADER','PICKUP','VIEWER') NOT NULL DEFAULT 'VIEWER', is_active BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(campus_id) REFERENCES campuses(id) ON DELETE CASCADE);
CREATE TABLE service_sessions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, campus_id INT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NULL, is_open BOOLEAN NOT NULL DEFAULT TRUE, FOREIGN KEY(campus_id) REFERENCES campuses(id) ON DELETE CASCADE);
CREATE TABLE attendance (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, service_session_id INT UNSIGNED NOT NULL, child_id INT UNSIGNED NOT NULL, class_id INT UNSIGNED NOT NULL, status ENUM('CHECKED_IN','PICKUP_REQUESTED','PICKED_UP') NOT NULL DEFAULT 'CHECKED_IN', checked_in_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, pickup_requested_at DATETIME NULL, picked_up_at DATETIME NULL, UNIQUE KEY one_child_per_service(service_session_id,child_id), FOREIGN KEY(service_session_id) REFERENCES service_sessions(id) ON DELETE CASCADE, FOREIGN KEY(child_id) REFERENCES children(id) ON DELETE CASCADE, FOREIGN KEY(class_id) REFERENCES classes(id));
CREATE TABLE pickup_events (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, attendance_id INT UNSIGNED NOT NULL, requested_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, released_at DATETIME NULL, released_to_guardian_id INT UNSIGNED NULL, released_to_authorized_pickup_id INT UNSIGNED NULL, verification_method VARCHAR(150), notes TEXT, FOREIGN KEY(attendance_id) REFERENCES attendance(id) ON DELETE CASCADE, FOREIGN KEY(released_to_guardian_id) REFERENCES guardians(id) ON DELETE SET NULL, FOREIGN KEY(released_to_authorized_pickup_id) REFERENCES authorized_pickups(id) ON DELETE SET NULL);
CREATE TABLE calendar_years (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, year_number SMALLINT UNSIGNED NOT NULL UNIQUE);
CREATE TABLE calendar_months (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, year_id INT UNSIGNED NOT NULL, month_number TINYINT UNSIGNED NOT NULL, UNIQUE KEY one_month_per_year(year_id,month_number), FOREIGN KEY(year_id) REFERENCES calendar_years(id) ON DELETE CASCADE);
CREATE TABLE calendar_weeks (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, month_id INT UNSIGNED NOT NULL, week_number TINYINT UNSIGNED NOT NULL CHECK(week_number BETWEEN 1 AND 4), UNIQUE KEY one_week_per_month(month_id,week_number), FOREIGN KEY(month_id) REFERENCES calendar_months(id) ON DELETE CASCADE);
CREATE TABLE daily_attendance (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, child_id INT UNSIGNED NOT NULL, attendance_date DATE NOT NULL, calendar_year_id INT UNSIGNED NOT NULL, calendar_month_id INT UNSIGNED NOT NULL, calendar_week_id INT UNSIGNED NOT NULL, status ENUM('PRESENT','ABSENT') NOT NULL DEFAULT 'PRESENT', recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY one_tick_per_child_day(child_id,attendance_date), FOREIGN KEY(child_id) REFERENCES children(id) ON DELETE CASCADE, FOREIGN KEY(calendar_year_id) REFERENCES calendar_years(id), FOREIGN KEY(calendar_month_id) REFERENCES calendar_months(id), FOREIGN KEY(calendar_week_id) REFERENCES calendar_weeks(id));
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, campus_id INT UNSIGNED NOT NULL, actor_id INT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT UNSIGNED NOT NULL, metadata JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(campus_id) REFERENCES campuses(id) ON DELETE CASCADE);
